html:
{%- set card = get_customer_card(doc.name) -%}
{%- macro section(title) -%}<h4 class="tp-card-h">{{ _(title) }}</h4>{%- endmacro -%}
{%- macro not_recorded() -%}<p class="text-muted">{{ _("Not recorded") }}</p>{%- endmacro -%}
<style>
	.tp-card { font-size: 11px; }
	.tp-card h3 { margin: 0 0 2px; }
	.tp-card .tp-card-h { margin: 16px 0 6px; padding-bottom: 3px; border-bottom: 1px solid #ccc; font-size: 13px; }
	.tp-card table { width: 100%; border-collapse: collapse; margin-bottom: 4px; }
	.tp-card th, .tp-card td { border: 1px solid #ccc; padding: 3px 5px; vertical-align: top; text-align: left; }
	.tp-card th { background: #f3f3f3; }
	.tp-card .tp-info td { border: none; padding: 2px 8px 2px 0; }
	.tp-card .tp-info td.lbl { color: #666; width: 18%; }
	.tp-card .num { text-align: right; }
</style>
<div class="tp-card">
	<h3>{{ doc.customer_name }}</h3>
	<div class="text-muted">
		{{ _("Customer Code") }} {{ doc.name }} · {{ _(doc.customer_status) }}{% if doc.group_name %} · {{ doc.group_name }}{% endif %}
	</div>

	{{ section("Company") }}
	<table class="tp-info">
		<tr>
			<td class="lbl">{{ _("Industry") }}</td><td>{{ doc.industry_domain or "" }}</td>
			<td class="lbl">{{ _("Territory / Region") }}</td><td>{{ doc.territory_region or "" }}{% if doc.zone %} ({{ doc.zone }}){% endif %}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("Annual Turnover") }}</td><td>{% if doc.annual_turnover_cr %}₹ {{ doc.get_formatted("annual_turnover_cr") }} Cr{% endif %}</td>
			<td class="lbl">{{ _("Group Turnover") }}</td><td>{% if doc.group_turnover_cr %}₹ {{ doc.get_formatted("group_turnover_cr") }} Cr{% endif %}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("Established") }}</td><td>{{ doc.established_year or "" }}</td>
			<td class="lbl">{{ _("Employees") }}</td><td>{{ doc.total_employees or "" }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("Principals") }}</td><td>{{ card.principals | join(", ") }}</td>
			<td class="lbl">{{ _("Handled By") }}</td><td>{{ card.agents | join(", ") }}</td>
		</tr>
		<tr>
			<td class="lbl">{{ _("Address") }}</td>
			<td colspan="3">{{ (doc.customer_address or "") | replace("\n", ", ") }}{% if doc.plant_location %}, {{ doc.plant_location }}{% endif %}{% if doc.state %}, {{ doc.state }}{% endif %}{% if doc.pincode %} {{ doc.pincode }}{% endif %}</td>
		</tr>
	</table>

	{{ section("Plants") }}
	{% if doc.plants %}
	<table>
		<tr><th>{{ _("Code") }}</th><th>{{ _("Plant") }}</th><th>{{ _("Location") }}</th><th>{{ _("State") }}</th><th>{{ _("Address") }}</th></tr>
		{% for p in doc.plants %}
		<tr><td>{{ p.record or "" }}</td><td>{{ p.plant_name }}{% if not p.is_active %} ({{ _("inactive") }}){% endif %}</td><td>{{ p.plant_location or "" }}</td><td>{{ p.state or "" }}</td><td>{{ p.plant_address or "" }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Contacts") }}
	{% if card.contacts %}
	<table>
		<tr><th>{{ _("Name") }}</th><th>{{ _("Designation") }}</th><th>{{ _("Department") }}</th><th>{{ _("Phone") }}</th><th>{{ _("Email") }}</th></tr>
		{% for c in card.contacts %}
		<tr><td>{{ c.person_name }}{% if c.is_primary %} ★{% endif %}</td><td>{{ c.designation or "" }}</td><td>{{ c.department or "" }}</td><td>{{ c.phone or "" }}</td><td>{{ c.email or "" }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Products Range & Production Volume") }}
	{% if card.production %}
	<table>
		<tr><th>{{ _("Product") }}</th><th>{{ _("Category") }}</th><th>{{ _("Plant") }}</th><th class="num">{{ _("Production Volume") }}</th></tr>
		{% for r in card.production %}
		<tr><td>{{ r.product }}</td><td>{{ r.category }}</td><td>{{ r.plant }}</td><td class="num">{{ frappe.format(r.volume, {"fieldtype": "Float"}) }} {{ r.unit }}{% if r.frequency %} / {{ _(r.frequency) }}{% endif %}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Turnover") }}
	{% if card.turnovers %}
	<table>
		<tr><th>{{ _("Financial Year") }}</th><th>{{ _("Plant") }}</th><th class="num">{{ _("Amount") }}</th><th>{{ _("Remarks") }}</th></tr>
		{% for r in card.turnovers %}
		<tr><td>{{ r.financial_year }}</td><td>{{ r.plant }}</td><td class="num">{{ frappe.format(r.amount, {"fieldtype": "Float"}) }} {{ r.unit }}{% if r.frequency %} ({{ _(r.frequency) }}){% endif %}</td><td>{{ r.remarks or "" }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Segments & Applications") }}
	{% if card.segments %}
	<table>
		<tr><th>{{ _("Segment") }}</th><th>{{ _("Line") }}</th><th>{{ _("Plant") }}</th><th>{{ _("Applications") }}</th><th class="num">{{ _("Monthly Volume") }}</th><th class="num">{{ _("Turnover (Cr)") }}</th><th>{{ _("Competitors") }}</th></tr>
		{% for r in card.segments %}
		<tr><td>{{ r.segment_title }}</td><td>{{ r.sub_category_line or "" }}</td><td>{{ r.plant_title }}</td><td>{{ r.applications }}{% if r.application_notes %}<br><span class="text-muted">{{ r.application_notes }}</span>{% endif %}</td><td class="num">{{ frappe.format(r.volume, {"fieldtype": "Float"}) }} {{ r.unit_title }}</td><td class="num">{{ frappe.format(r.segment_turnover_cr, {"fieldtype": "Float"}) }}</td><td>{{ r.competitors }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Abrasive Consumption") }}
	{% if card.consumption %}
	<table>
		<tr><th>{{ _("Type") }}</th><th>{{ _("Application") }}</th><th>{{ _("Plant") }}</th><th class="num">{{ _("Quantity") }}</th><th>{{ _("Current Supplier") }}</th><th>{{ _("Remarks") }}</th></tr>
		{% for r in card.consumption %}
		<tr><td>{{ r.consumption_type_title }}</td><td>{{ r.application_title }}</td><td>{{ r.plant_title }}</td><td class="num">{{ frappe.format(r.quantity, {"fieldtype": "Float"}) }} {{ r.unit_title }}{% if r.frequency %} / {{ _(r.frequency) }}{% endif %}</td><td>{{ r.current_supplier_title }}</td><td>{{ r.remarks or "" }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Current Wheel Usage") }}
	{% if card.wheel_specs %}
	<table>
		<tr><th>#</th><th>{{ _("Application") }}</th><th>{{ _("Wheel Spec") }}</th><th>{{ _("Wheel Size") }}</th><th>{{ _("Wheel Speed") }}</th><th>{{ _("Pitch Range") }}</th><th class="num">{{ _("Consumption / Year") }}</th><th>{{ _("Competitor") }}</th></tr>
		{% for r in card.wheel_specs %}
		<tr><td>{{ loop.index }}</td><td>{{ r.application_title }}</td><td>{{ r.wheel_specification or "" }}</td><td>{{ r.wheel_size or "" }}</td><td>{{ r.wheel_speed or "" }}</td><td>{{ r.pitch_range or "" }}</td><td class="num">{{ frappe.format(r.annual_consumption, {"fieldtype": "Float"}) }} {{ r.consumption_unit_title }}</td><td>{{ r.competitors_title }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Manufacturing") }}
	{% if card.manufacturing %}
	<table>
		<tr><th>{{ _("Manufacturing") }}</th><th>{{ _("Process") }}</th><th>{{ _("In-House / Outsourced") }}</th><th>{{ _("Plant") }}</th><th>{{ _("Description") }}</th></tr>
		{% for r in card.manufacturing %}
		<tr><td>{{ r.manufacturing_type or "" }}</td><td>{{ r.process_name or "" }}</td><td>{{ r.process_type or "" }}</td><td>{{ r.plant_title }}</td><td>{{ r.description or "" }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}

	{{ section("Machine Details") }}
	{% if card.machines %}
	<table>
		<tr><th>{{ _("Machine / Process") }}</th><th>{{ _("Maker(s)") }}</th><th class="num">{{ _("Qty") }}</th><th>{{ _("Plant") }}</th><th>{{ _("Remarks") }}</th></tr>
		{% for m in card.machines %}
		<tr><td>{{ m.machine_type }}</td><td>{{ m.maker or "" }}</td><td class="num">{{ m.quantity or "" }}</td><td>{{ m.plant }}</td><td>{{ m.remarks or "" }}</td></tr>
		{% endfor %}
	</table>
	{% else %}{{ not_recorded() }}{% endif %}
</div>
